import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngineConfig, HalEngine} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionStore, SessionListOptions} from '../types/sessionStore.js';
import type {IncomingMessage, OutgoingMessage} from '../types/messages.js';
import {setLogger} from '../shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

interface Row {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}
interface Frame {
  type: string;
  sessionId?: string;
  code?: string;
  message?: string;
  conversations?: Row[];
  [key: string]: unknown;
}

const engines: HalEngine[] = [];
const sockets: WebSocket[] = [];
const logs: Array<{level: string; message: string; fields?: Record<string, unknown>}> = [];
const logger = Object.fromEntries(
  ['debug', 'info', 'warn', 'error'].map(level => [
    level,
    (_category: string, message: string, fields?: Record<string, unknown>) => logs.push({level, message, fields}),
  ])
) as NonNullable<HalEngineConfig['logger']>;

beforeEach(() => { logs.length = 0; });
afterEach(async () => {
  for (const socket of sockets.splice(0)) socket.terminate();
  for (const engine of engines.splice(0)) await engine.stop();
  setLogger();
});

async function start(
  session: SessionStore,
  history: {enabled: boolean} | undefined = {enabled: true},
  hooks?: NonNullable<HalEngineConfig['orchestrator']>['hooks'],
  resume = true
) {
  // Structural assignment keeps today's config compilable while exercising the public opt-in at runtime.
  const transport = {history, resume: {enabled: resume}};
  const engine = createHalEngine({
    provider: {type: 'mock'}, prompt: {identity: 'Acceptance conversation'},
    session, transport, auth: {ws: async () => ({id: 'owner'})}, logger,
    orchestrator: {hooks},
  });
  engines.push(engine);
  await engine.start(0);
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
}

async function until(check: () => boolean) {
  const deadline = Date.now() + 2000;
  while (!check() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
  expect(check()).toBe(true);
}

async function connect(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'owner-token']);
  sockets.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await until(() => frames.some(frame => frame.type === 'connected'));
  const send = (frame: unknown) => socket.send(JSON.stringify(frame));
  const settle = async () => {
    const timestamp = frames.length + 1;
    send({type: 'ping', timestamp});
    await until(() => frames.some(frame => frame.type === 'pong' && frame.timestamp === timestamp));
  };
  await settle();
  expect(frames.filter(frame => frame.type === 'conversation_list')).toEqual([]);
  const connected = frames[0];
  frames.length = 0;
  return {socket, frames, connected, send, settle};
}

async function request(peer: Awaited<ReturnType<typeof connect>>, frame: unknown) {
  peer.frames.length = 0;
  peer.send(frame);
  await until(() => peer.frames.some(item => item.type === 'conversation_list' || item.type === 'error'));
  await peer.settle();
  return peer.frames.filter(item => item.type "'!== '"'pong');
}

// Records the real call and delegates every result to the shipped store, without substituting its behavior.
class RecordedStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options: SessionListOptions | undefined}> = [];
  override listFor(userId: string | number, options?: SessionListOptions) {
    this.calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

function originalPort(store: InMemorySessionStore): SessionStore {
  return {
    create: store.create.bind(store), get: store.get.bind(store), delete: store.delete.bind(store),
    count: store.count.bind(store), clear: store.clear.bind(store),
  };
}

it('validates history pagination without changing existing message literals', () => {
  const oldIncoming: IncomingMessage[] = [{type: 'ping', timestamp: 1}, {type: 'user_message', content: 'hello'}];
  const oldOutgoing: OutgoingMessage[] = [
    {type: 'connected', sessionId: 's', message: 'Connected', examplePrompts: []},
    {type: 'connected', sessionId: 's', message: 'Connected', examplePrompts: [], resumed: true, entryCount: 1},
    {type: 'connected', sessionId: 's', message: 'Connected', examplePrompts: [], resumed: false, resumeFailure: 'expired'},
    {type: 'entry_upsert', index: 0, entry: {role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}},
    {type: 'entry_delta', index: 1, delta: 'hello'}, {type: 'entry_commit', index: 1},
    {type: 'entry_skip', index: 2}, {type: 'stream_end'}, {type: 'pong', timestamp: 1},
    {type: 'error', code: 'SERVER_ERROR', message: 'Failed'},
  ];
  expect(JSON.parse(JSON.stringify(oldOutgoing))).toEqual(oldOutgoing);
  for (const frame of oldIncoming) expect(validateMessage(frame)).toEqual({valid: true, data: frame});
  const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's'};
  for (const fields of [{}, {limit: 1}, {limit: 200, before}]) {
    const frame = {type: 'list_conversations', ...fields};
    expect(validateMessage({...frame, userId: 'intruder'})).toEqual({valid: true, data: frame});
  }
  for (const limit of [0, 201, 1.5, '10', null]) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  }
  for (const cursor of ['not a date', before.updatedAt, {}, {updatedAt: before.updatedAt}, {sessionId: 's'}, {...before, updatedAt: 'bad'}, {...before, sessionId: 3}, null]) {
    expect(validateMessage({type: 'list_conversations', before: cursor})).toEqual({valid: false, error: expect.stringMatching(/before/i)});
  }
});

it('lists only the authenticated user with ISO metadata and pages into the existing resume path', async () => {
  const store = new RecordedStore();
  for (const id of ['a', 'b']) {
    store.create(id, 'owner', {authHeaders: {Authorization: 'private-token'}}).entries.push({
      role: 'user', content: "'`private-${id}`, timestamp: '"'2020-01-01T00:00:00.000Z',
    });
  }
  store.create('other-user', 'intruder');
  const base = await start(store);
  const peer = await connect(base);
  const expected = store.listFor('owner').map(row => ({...row, createdAt: row.createdAt.toISOString(), updatedAt: row.updatedAt.toISOString()}));
  store.calls.length = 0;
  expect(await request(peer, {type: 'list_conversations', userId: 'intruder'})).toEqual([{type: 'conversation_list', conversations: expected}]);
  expect(expected).toHaveLength(3);
  expect(expected[0].sessionId).toBe(peer.connected.sessionId);
  expect(store.calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  const seen: Row[] = [];
  let before: {updatedAt: string; sessionId: string} | undefined;
  for (let page = 0; page < 4; page++) {
    const result = await request(peer, {type: 'list_conversations', limit: 1, before});
    expect(store.calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
    expect(result).toEqual([{type: 'conversation_list', conversations: expected.slice(page, page + 1)}]);
    const row = result[0].conversations?.[0];
    if (row) { seen.push(row); before = {updatedAt: row.updatedAt, sessionId: row.sessionId}; }
  }
  expect(seen).toEqual(expected);
  const reopened = await connect("'`${base}?sessionId=${seen[1].sessionId}`);
  expect(reopened.connected).toMatchObject({resumed: true, sessionId: seen[1].sessionId, entryCount: 1});
  // connect clears replay frames after the pong; ask a second real connection to retain its replay via the stored entry count.
  expect(store.get(seen[1].sessionId)?.entries).toEqual([{role: '"'user', content: "'`private-${seen[1].sessionId}`, timestamp: '"'2020-01-01T00:00:00.000Z'}]);
});

it('refuses disabled or unavailable history with UNSUPPORTED and warns when rows cannot be resumed', async () => {
  const store = new InMemorySessionStore();
  const cases: Array<{store: SessionStore; history?: {enabled: boolean}}> = [
    {store}, {store, history: {enabled: false}}, {store: originalPort(store), history: {enabled: true}},
  ];
  for (const item of cases) {
    const base = await start(item.store, item.history ?? {enabled: false});
    const peer = await connect(base);
    const frames = await request(peer, {type: 'list_conversations'});
    expect(frames).toEqual([{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]);
    expect(peer.socket.readyState).toBe(WebSocket.OPEN);
  }
  await start(store, {enabled: true}, undefined, false);
  expect(logs.some(line => line.level === 'warn' && /history/i.test(JSON.stringify(line)) && /resume/i.test(JSON.stringify(line)))).toBe(true);
});

it('distinguishes a store that cannot list from a failed store without exposing details or closing the socket', async () => {
  const client = new MongoClient('mongodb://127.0.0.1:1');
  await client.close();
  const collection = client.db('private-database').collection<MongoSessionDocument>('private-conversations');
  const legacyCollection = {
    findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  };
  for (const [listing, code] of [
    [new MongoSessionStore({collection}), 'SERVER_ERROR'],
    [new MongoSessionStore({collection: legacyCollection}), 'UNSUPPORTED'],
  ] as const) {
    // Real memory CRUD permits the upgrade; real Mongo listing exercises closed-driver and absent-find failures.
    const session = {...originalPort(new InMemorySessionStore()), listFor: listing.listFor.bind(listing)};
    const peer = await connect(await start(session));
    logs.length = 0;
    const frames = await request(peer, {type: 'list_conversations'});
    expect(frames).toEqual([{type: 'error', code, message: expect.any(String)}]);
    expect(JSON.stringify(frames)).not.toMatch(/Mongo|private-|connect|find/i);
    expect(peer.socket.readyState).toBe(WebSocket.OPEN);
    expect(logs.some(line => line.fields?.sessionId === peer.connected.sessionId)).toBe(true);
    expect(JSON.stringify(logs)).not.toMatch(/owner-token|private-/);
  }
});

it('answers history before stream_end while the same session turn is still running', async () => {
  let release = () => {};
  const gate = new Promise<void>(resolve => { release = resolve; });
  let streaming = false;
  const base = await start(new InMemorySessionStore(), {enabled: true}, {
    afterModelResponse: async () => { streaming = true; await gate; },
  });
  const peer = await connect(base);
  try {
    peer.send({type: 'user_message', content: 'a running turn'});
    await until(() => streaming && peer.frames.some(frame => frame.type === 'entry_delta'));
    expect(peer.frames.some(frame => frame.type === 'stream_end')).toBe(false);
    const frames = await request(peer, {type: 'list_conversations'});
    expect(frames.map(frame => frame.type)).toEqual(['conversation_list']);
    release();
    await until(() => peer.frames.some(frame => frame.type === 'stream_end'));
    expect(peer.frames.findIndex(frame => frame.type === 'conversation_list')).toBeLessThan(peer.frames.findIndex(frame => frame.type === 'stream_end'));
  } finally { release(); }
});
EOF"

